def _bind_server_run_id(config: dict[str, Any], run_id: str) -> None:
    """Bind checkpoint metadata to the server-created Run identity."""
    candidate = config.get("metadata")
    metadata = dict(candidate) if isinstance(candidate, Mapping) else {}
    metadata["run_id"] = run_id
    config["metadata"] = metadata

